// Bilingual, English first. The tagline is a single key, hero.title. No visible text uses a middle dot, semicolon,
// em dash or arrow. Ellipses only appear in truncated hashes (fmt.ts).
import { useSyncExternalStore } from 'react'

export type Lang = 'en' | 'fr'
const saved = (() => { try { return localStorage.getItem('archive-lang') } catch { return null } })()
let lang: Lang = new URLSearchParams(location.search).get('lang') === 'fr' || saved === 'fr' ? 'fr' : 'en'
const subs = new Set<() => void>()
export const getLang = () => lang
export function setLang(l: Lang) {
  lang = l
  try { localStorage.setItem('archive-lang', l) } catch { /* private browsing */ }
  document.documentElement.lang = l
  setTitle()
  subs.forEach((f) => f())
}
export const useLang = () => useSyncExternalStore((f) => { subs.add(f); return () => { subs.delete(f) } }, () => lang)

