export type TKey = Key
export function t(k: Key, vars?: Record<string, string | number>) {
  let s = (lang === 'fr' ? FR : EN)[k] ?? EN[k] ?? k
  if (vars) for (const [a, b] of Object.entries(vars)) s = s.split(`{${a}}`).join(String(b))
  return s
}
document.documentElement.lang = lang
/** The tab title follows the hero title; a page that sets its own title says so with data-title */
// A title set by a page also follows the language (its key is looked up in either language)
export function setTitle() {
  const own = document.documentElement.dataset.title
  if (!own) { document.title = `ArcHive. ${t('hero.title')}`; return }
  const k = (Object.keys(EN) as Key[]).find((x) => EN[x] === own || FR[x] === own)
  document.title = k ? t(k) : own
}
setTitle()
